	input: RoutinePayloadInput,
	mode: "create" | "update",
): RoutinePayloadResult {
	let usesRepRanges = false;
	const exercises = input.exercises.map((exercise) => {
		const sets = buildRoutineSets(exercise.sets, mode);
		if (
			sets.some(
				(set) =>
					set.rep_range != null &&
